// Cloud Homework Sync Engine for M.1/4 SMT

// Compact serialization using 10-character hex bitmask for 39 students
window.serializeTasks = function(tasks) {
    if (!Array.isArray(tasks)) return [];
    var db = window.REAL_STUDENT_DB || [];
    var noToId = {};
    db.forEach(function(s) { noToId[s.no] = s.student_id.toString(); });

    return tasks.map(function(t) {
        var mask = '';
        var pendingSet = new Set((t.pendingStudentIds || []).map(String));
        for (var no = 1; no <= 39; no++) {
            var sid = noToId[no];
            mask += (sid && pendingSet.has(sid)) ? '1' : '0';
        }
        var hex = '';
        try {
            hex = BigInt('0b1' + mask).toString(16);
        } catch(e) {
            hex = mask;
        }

        return {
            id: t.id,
            s: t.subject,
            t: t.title,
            d: t.dueDate,
            c: t.createdAt,
            m: hex,
            f: t.attachedFiles || []
        };
    });
};

window.deserializeTasks = function(compactList) {
    if (!Array.isArray(compactList)) return [];
    var db = window.REAL_STUDENT_DB || [];
    var noToId = {};
    db.forEach(function(s) { noToId[s.no] = s.student_id.toString(); });

    return compactList.map(function(c) {
        var pendingIds = [];
        var mask = '';
        if (c.m) {
            if (c.m.length <= 15) {
                try {
                    mask = BigInt('0x' + c.m).toString(2).slice(1);
                } catch(e) {
                    mask = c.m;
                }
            } else {
                mask = c.m;
            }
            for (var i = 0; i < mask.length; i++) {
                if (mask[i] === '1') {
                    var sid = noToId[i + 1];
                    if (sid) pendingIds.push(sid);
                }
            }
        } else if (c.p === 'all') {
            pendingIds = db.map(function(s) { return s.student_id.toString(); });
        } else if (typeof c.p === 'string' && c.p.trim() !== '') {
            var parts = c.p.split(',').map(function(s) { return s.trim(); });
            parts.forEach(function(part) {
                var foundByNo = db.find(function(s) { return s.no.toString() === part; });
                if (foundByNo) {
                    pendingIds.push(foundByNo.student_id.toString());
                } else {
                    pendingIds.push(part);
                }
            });
        } else if (Array.isArray(c.pendingStudentIds)) {
            pendingIds = c.pendingStudentIds.map(String);
        }

        return {
            id: c.id,
            subject: c.s || c.subject || '',
            title: c.t || c.title || '',
            dueDate: c.d || c.dueDate || '',
            createdAt: c.c || c.createdAt || '',
            pendingStudentIds: pendingIds,
            attachedFiles: c.f || c.attachedFiles || []
        };
    });
};

